import sys
sys.setrecursionlimit(300000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Track which clauses contain which variables
    var_to_clauses = [[] for _ in range(m + 1)]  # var_to_clauses[v] = [(clause_idx, literal)]
    var_count = [0] * (m + 1)

    clauses = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        ki = parts[0]
        literals = parts[1:]
        clauses.append(literals)
        for lit in literals:
            v = abs(lit)
            var_to_clauses[v].append((i, lit))
            var_count[v] += 1

    # Build implication graph for 2-SAT
    # Node i represents xi is TRUE
    # Node i+m represents xi is FALSE
    adj = [[] for _ in range(2 * m + 1)]
    NOT = [0] * (2 * m + 1)

    for i in range(1, m + 1):
        NOT[i] = i + m
        NOT[i + m] = i

    # For each clause, add implications
    # Clause: (l1 OR l2 OR ... OR lk)
    # Implication: For each literal lj, if lj is false, then all other literals must be true

    for idx, literals in enumerate(clauses):
        if len(literals) == 1:
            # Unit clause: l1 must be true
            # ¬l1 -> l1
            lit = literals[0]
            if lit < 0:
                adj[lit + m].append(abs(lit))  # ¬(-x) = x -> x
            else:
                adj[lit + m].append(lit)  # ¬x -> x
        else:
            # Multiple literals in clause
            # For each literal lj: ¬lj -> all other literals li
            for j, lit_j in enumerate(literals):
                neg_lj = lit_j + m if lit_j < 0 else abs(lit_j)
                for i in range(len(literals)):
                    if i == j:
                        continue
                    lit_i = literals[i]
                    adj[neg_lj].append(lit_i if lit_i > 0 else abs(lit_i))

    # Build using 2-SAT approach with connected components
    # Check if any variable and its negation are in the same SCC

    visited = [False] * (2 * m + 1)
    scc_id = [-1] * (2 * m + 1)
    scc_count = 0
    order = []

    # First pass: get finish order
    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(1, 2 * m + 1):
        if not visited[i]:
            dfs1(i)

    # Second pass: assign SCC IDs (work in reverse order)
    visited2 = [False] * (2 * m + 1)
    reverse_adj = [[] for _ in range(2 * m + 1)]

    # Build reverse graph
    for u in range(1, 2 * m + 1):
        for v in adj[u]:
            reverse_adj[v].append(u)

    def dfs2(u):
        visited2[u] = True
        scc_id[u] = scc_count
        for v in reverse_adj[u]:
            if not visited2[v]:
                dfs2(v)

    for u in reversed(order):
        if not visited2[u]:
            dfs2(u)
            scc_count += 1

    # Check for contradictions
    for i in range(1, m + 1):
        if scc_id[i] == scc_id[i + m]:
            return "NO"

    # Build solution
    result = ['0'] * m
    for i in range(1, m + 1):
        if scc_id[i] > scc_id[i + m]:
            result[i - 1] = '1'

    return "YES\n" + ''.join(result)

