def solution(s):
    from collections import defaultdict

    lines = s.strip().split('\n')
    idx = 0
    if idx >= len(lines):
        return ''

    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1
        if idx >= len(lines):
            break
        a = list(map(int, lines[idx].strip().split()))
        idx += 1

        # Find the longest non-decreasing subsequence using DP
        # We track the maximum length ending at each position
        dp = [0] * n
        for i in range(n):
            dp[i] = 1  # Minimum is 1 (just the element itself)
            for j in range(i):
                if a[j] <= a[i]:
                    dp[i] = max(dp[i], dp[j] + 1)

        k = max(dp) if dp else 0
        results.append(str(n - k))

    return '\n'.join(results)

def solution(n_str):
    n = int(n_str.strip())
    if n == 0:
        return '0'

    count = 0
    d = 2
    while d * d <= n:
        while n % d == 0:
            count += 1
            n //= d
        d += 1
    if n > 1:
        count += 1

    return str(count)

