def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    n = int(lines[0])
    strings = lines[1:n+1]

    # Precompute sorted versions for each string
    sorted_list = [''.join(sorted(s)) for s in strings]

    # Count how many pairs have different sorted versions
    diff_count = 0
    same_count = 0

    for i in range(n):
        for j in range(i + 1, n):
            if sorted_list[i] != sorted_list[j]:
                diff_count += 1

    # Strings with different sorted versions contribute 1337
    # Strings with same sorted versions but not identical contribute 2
    # Strings that are identical contribute 0

    # Count identical pairs
    identical_pairs = 0
    for i in range(n):
        for j in range(i + 1, n):
            if strings[i] == strings[j]:
                identical_pairs += 1

    # Count pairs with same sorted version (including identical)
    same_sorted_pairs = 0
    for i in range(n):
        for j in range(i + 1, n):
            if sorted_list[i] == sorted_list[j]:
                same_sorted_pairs += 1

    # Total results
    result = diff_count * 1337 + (same_sorted_pairs - identical_pairs) * 2

    return str(result) + '\n'

