def bfs_check(start, end, n, adj, removed):
    """Check if start can reach end given removed edges"""
    if start == end:
        return False  # Already at destination
    visited = [False] * (n + 1)
    queue = deque([start])
    visited[start] = True

    while queue:
        u = queue.popleft()
        if u == end:
