def ceil_log2(x):
    """Calculate ceil(log2(x)) for x >= 1, returns 1 if x=1"""
    if x == 1:
        return 0
    if x == 0:
        return 0
    import math
    return max(0, math.ceil(math.log2(x)))

def compute_w(n, weights, graph):
    """Compute weight w for a tree"""
    # Find minimum weight node
