        mapping = {}

        for i in range(m):
            u = s_sub[i]
            v = t_sub[i]
            if u not in mapping:
                mapping[u] = v

        # Check if mapping is bijective (one-to-one correspondence)
        # This ensures each character maps to exactly one, and vice versa
        valid = True
        forward_used = set()  # Track which source characters we've seen
        reverse_used = set()  # Track which target characters we've seen
        reverse_map = {}      # Target -> Source mapping for validation

        for u, v in mapping.items():
            # If this source character hasn't been seen before in this substring mapping
            if u not in forward_used:
                # Check if this target is already used by a different source
                if v in reverse_used and reverse_map[v] != u:
                    valid = False
                    break
                reverse_used.add(v)
                reverse_map[v] = u

            # Add the source character
            forward_used.add(u)

        # Additional validation: ensure reverse mapping is also consistent
        for v, u in reverse_map.items():
            if u not in forward_used or mapping.get(u) != v:
                valid = False
                break

