def solution(input_str):
    MOD = 998244353

    n, k, l = map(int, input_str.strip().split())

    def power(a, b, m):
        result = 1
        a %= m
        while b > 0:
            if b & 1:
                result = result * a % m
            a = a * a % m
            b >>= 1
        return result

    def inverse(n):
        return power(n, MOD - 2, MOD)

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        num = 1
        den = 1
        for i in range(k):
            num = num * (n - i) % MOD
            den = den * (i + 1) % MOD
        return num * inverse(den) % MOD

    # We need to compute:
    # Expected = l * ∫₀¹ Σ(i=k to n) C(n,i) * [2t(1-t)]^i * [1 - 2t(1-t)]^(n-i) dt

    # Let's expand: 2t(1-t) = 2(t - t²) = 2(Σ C(i-m, j)(-1)^m t^{j+i}) / (but we use direct expansion)
    # Actually: [2t(1-t)]^i = 2^i * (t - t²)^i = 2^i * Σ C(i, j) t^j * (-1)^j * t^{2j} = 2^i * Σ C(i, j) * (-1)^j * t^{2j+j}
    # No wait, (t - t²)^i = Σ C(i, j) t^j * (-t²)^(i-j) = Σ C(i, j) * (-1)^(i-j) * t^{2(i-j)+j}
    # So = Σ C(i, j) * (-1)^(i-j) * t^{2i-j}

    # Similarly for [1 - 2t(1-t)] = 1 - 2t + 2t²
    # [1 - 2t + 2t²]^(n-i) is trickier

    # Let me use a different approach - expand both in terms of t

    # [2t(1-t)]^i = 2^i * (t - t^2)^i
    # = 2^i * Σ_{j=0 to i} C(i, j) * t^j * (-1)^{i-j} * t^{2(i-j)}
    # = 2^i * Σ_{j=0 to i} C(i, j) * (-1)^{i-j} * t^{2i - j}

    # [1 - 2t(1-t)]^m = [1 - (2t - 2t^2)]^m = Σ_{a=0 to m} C(m, a) * 1^{m-a} * (-1)^a * (2t - 2t^2)^a
    # = Σ_{a=0 to m} C(m, a) * (-1)^a * [2^2 * (t - t^2)^a]
    # = Σ_{a=0 to m} C(m, a) * (-1)^a * 4^a * Σ_{b=0 to a} C(a, b) * (-1)^{a-b} * t^{2a-b}
    # = Σ_{a=0 to m} Σ_{b=0 to a} C(m, a) * C(a, b) * (-1)^{a+a-b} * 4^a * t^{2a-b}
    # = Σ_{a=0 to m} Σ_{b=0 to a} C(m, a) * C(a, b) * (-1)^{2a-b} * 4^a * t^{2a-b}
    # Note (-1)^{2a-b} = (-1)^{-b} = (-1)^b
    # = Σ_{a=0 to m} Σ_{b=0 to a} C(m, a) * C(a, b) * (-1)^b * 4^a * t^{2a-b}

    total_sum = 0

    for i in range(k, n + 1):
        # Coefficient for [2t(1-t)]^i
        coeff1 = comb(n, i)
        coeff1 = coeff1 * pow(2, i, MOD) % MOD

        # For [1 - 2t(1-t)]^(n-i)
        m = n - i

        # Expand [1 - 2t(1-t)]^m
        # = Σ_{a=0 to m} C(m, a) * (-1)^a * (2t - 2t^2)^a
        # (2t - 2t^2)^a = 2^a * (t - t^2)^a = 2^a * Σ_{b=0 to a} C(a, b) * t^b * (-t^2)^(a-b)
        # = 2^a * Σ_{b=0 to a} C(a, b) * (-1)^(a-b) * t^{b + 2(a-b)}
        # = 2^a * Σ_{b=0 to a} C(a, b) * (-1)^(a-b) * t^{2a - b}

